// Speed control: hold 0.2 m/s with the encoders and a PI loop. The target steps from 0 to 0.2 m/s at 2 s.
// The controller is the reference PID of the iynk instrument; the response is the speed worked out from the encoder counts.
const int PWMA = 5, AIN1 = 7, AIN2 = 8;      // left motor
const int PWMB = 6, BIN1 = 10, BIN2 = 4;     // right motor
const int STBY = 9;
const int ENC_L_A = 2, ENC_L_B = 11;         // left encoder; A is on an interrupt pin
const int ENC_R_A = 3, ENC_R_B = 12;         // right encoder
const int LOOP_PIN = 13;                     // flips at the top of loop(), so the loop period shows on the logic analyzer

const bool SLOW_LOOP = false;                // the loop-too-slow fault sets this to true

const float COUNTS_PER_REV = 528.0;          // 11 pulses per motor revolution on channel A, times the 48:1 gearbox (iynk assumption)
const float WHEEL_CIRC_M = 0.2042;           // 65 mm wheel
const float TARGET_MPS = 0.2;
const unsigned long STEP_MS = 2000;

const float KP = 1.5;
const float KI = 5.0;
const float KD = 0.01;
const float TF = 0.04;                       // derivative filter time constant, seconds
const float I_MAX = 0.5;
const float U_MIN = 0.0;
const float U_MAX = 1.0;

volatile long leftCount = 0;
volatile long rightCount = 0;

float integral = 0;
float dFilt = 0;
float lastY = 0;
long lastLeft = 0;
long lastRight = 0;
unsigned long lastStep = 0;
bool heartbeat = false;

void countLeft() {
  if (digitalRead(ENC_L_B)) leftCount--;
  else leftCount++;
}

void countRight() {
  if (digitalRead(ENC_R_B)) rightCount--;
  else rightCount++;
}

void wheel(int in1, int in2, int pwm, int speed) {
  digitalWrite(in1, speed >= 0 ? HIGH : LOW);
  digitalWrite(in2, speed >= 0 ? LOW : HIGH);
  analogWrite(pwm, constrain(abs(speed), 0, 255));
}

void drive(int speed) {
  wheel(AIN1, AIN2, PWMA, speed);
  wheel(BIN1, BIN2, PWMB, speed);
}

void setup() {
  Serial.begin(115200);
  for (int p = 4; p <= 10; p++) pinMode(p, OUTPUT);
  pinMode(LOOP_PIN, OUTPUT);
  pinMode(ENC_L_A, INPUT);
  pinMode(ENC_L_B, INPUT);
  pinMode(ENC_R_A, INPUT);
  pinMode(ENC_R_B, INPUT);
  attachInterrupt(digitalPinToInterrupt(ENC_L_A), countLeft, RISING);
  attachInterrupt(digitalPinToInterrupt(ENC_R_A), countRight, RISING);
  digitalWrite(STBY, HIGH);
  lastStep = millis();
}

void loop() {
  heartbeat = !heartbeat;
  digitalWrite(LOOP_PIN, heartbeat);

  unsigned long now = millis();
  float dt = (now - lastStep) / 1000.0;
  lastStep = now;

  noInterrupts();
  long left = leftCount;
  long right = rightCount;
  interrupts();

  float turns = ((left - lastLeft) + (right - lastRight)) / 2.0 / COUNTS_PER_REV;
  lastLeft = left;
  lastRight = right;
  float y = dt > 0 ? turns * WHEEL_CIRC_M / dt : 0;

  float setpoint = now < STEP_MS ? 0.0 : TARGET_MPS;
  float e = setpoint - y;
  float a = dt / (dt + TF);
  if (dt > 0) dFilt += a * ((lastY - y) / dt - dFilt);   // the first pass has dt 0
  lastY = y;

  float p = KP * e;
  float d = KD * dFilt;
  float iNext = constrain(integral + KI * dt * e, -I_MAX, I_MAX);
  float raw = p + iNext + d;
  bool winding = (raw > U_MAX && e > 0) || (raw < U_MIN && e < 0);
  if (!winding) integral = iNext;
  float u = constrain(p + integral + d, U_MIN, U_MAX);

  drive((int)(u * 255));

  Serial.print("pid ");
  Serial.print(now);
  Serial.print(" ");
  Serial.print(setpoint, 4);
  Serial.print(" ");
  Serial.print(y, 4);
  Serial.print(" ");
  Serial.print(u, 4);
  Serial.print(" ");
  Serial.println(integral, 4);

  delay(SLOW_LOOP ? 40 : 20);
}
